<?php
/** @var array<string,mixed> $occurrence */
/** @var bool $canRecover */
require SMTT_CIF_GESTAO_PATH . 'templates/layout/header.php';
$fmt = static fn($value): string => is_string($value) && $value !== '' ? wp_date('d/m/Y H:i', strtotime($value . ' UTC')) : '—';

$returnToReport = null;
if (isset($_GET['retorno'])) {
    $candidate = wp_validate_redirect((string)wp_unslash($_GET['retorno']), '');
    $reportsPath = wp_parse_url(home_url('/cif/relatorios'), PHP_URL_PATH);
    $candidatePath = $candidate !== '' ? wp_parse_url($candidate, PHP_URL_PATH) : null;
    if (is_string($candidate) && $candidate !== '' && is_string($reportsPath) && $candidatePath === $reportsPath) {
        $returnToReport = $candidate;
    }
}
?>
<section class="cif-page-head"><div><p class="cif-eyebrow">Ocorrência CIF</p><h1><?= esc_html((string)$occurrence['tipo_label']) ?></h1><p><strong><?= esc_html((string)$occurrence['nome_completo']) ?></strong> · Matrícula <?= esc_html((string)$occurrence['matricula']) ?> · <a href="<?= esc_url(home_url('/cif/emissoes/'.rawurlencode((string)$occurrence['emissao_uuid']))) ?>"><code><?= esc_html((string)$occurrence['codigo_validacao']) ?></code></a></p></div><div class="cif-inline-actions"><?php if ($returnToReport !== null): ?><a class="cif-button cif-button--ghost" href="<?= esc_url($returnToReport) ?>">Voltar ao relatório</a><?php endif; ?><span class="cif-badge"><?= esc_html((string)$occurrence['status_label']) ?></span></div></section>
<?php if($notice): ?><div class="cif-alert cif-alert--<?= esc_attr($notice['type']) ?>"><?= esc_html($notice['text']) ?></div><?php endif; ?>
<?php if($error): ?><div class="cif-alert cif-alert--error"><?= esc_html($error) ?></div><?php endif; ?>
<div class="cif-detail-grid"><section class="cif-panel"><h2>Registro</h2><dl class="cif-definition-list">
<div><dt>Fato</dt><dd><?= esc_html($fmt($occurrence['data_fato'])) ?></dd></div><div><dt>Comunicação</dt><dd><?= esc_html($fmt($occurrence['data_comunicacao'])) ?></dd></div><div><dt>BO</dt><dd><?= esc_html((string)($occurrence['bo_numero'] ?: '—')) ?></dd></div><div><dt>Data do BO</dt><dd><?= $occurrence['bo_data'] ? esc_html(wp_date('d/m/Y',strtotime((string)$occurrence['bo_data'].' UTC'))) : '—' ?></dd></div><div><dt>Órgão</dt><dd><?= esc_html((string)($occurrence['bo_orgao'] ?: '—')) ?></dd></div><div><dt>Registrado por</dt><dd><?= esc_html((string)$occurrence['registrado_por_nome']) ?></dd></div><div><dt>Detalhes</dt><dd><?= nl2br(esc_html((string)($occurrence['detalhes'] ?: '—'))) ?></dd></div></dl></section>
<section class="cif-panel"><h2>Situação da emissão</h2><dl class="cif-definition-list"><div><dt>Validade</dt><dd><?= esc_html((string)$occurrence['status_validade']) ?></dd></div><div><dt>Situação física</dt><dd><?= esc_html((string)$occurrence['status_fisico']) ?></dd></div><div><dt>Recuperada em</dt><dd><?= esc_html($fmt($occurrence['recuperada_em'])) ?></dd></div></dl></section></div>
<?php if($occurrence['documents']!==[]): ?><section class="cif-section cif-panel"><h2>Documentos</h2><div class="cif-table-wrap"><table class="cif-table"><thead><tr><th>Tipo</th><th>Arquivo</th><th>Incluído</th></tr></thead><tbody><?php foreach($occurrence['documents'] as $doc): ?><tr><td><?= esc_html((string)$doc['tipo_documento']) ?></td><td><a target="_blank" rel="noopener" href="<?= esc_url(home_url('/cif/ocorrencias/arquivo/'.rawurlencode((string)$doc['arquivo_uuid']))) ?>"><?= esc_html((string)$doc['nome_original']) ?></a></td><td><?= esc_html($fmt($doc['incluido_em'])) ?> · <?= esc_html((string)$doc['incluido_por_nome']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if($currentUser->can('cif.processo.criar') && in_array((string)$occurrence['tipo_codigo'],['PERDA','FURTO','ROUBO','DANO','DESGASTE'],true)): ?>
<section class="cif-section cif-panel"><h2>Processo de nova emissão</h2><?php if (!empty($occurrence['processo_uuid'])): ?><p>Esta ocorrência já está vinculada a um processo administrativo.</p><a class="cif-button cif-button--secondary" href="<?= esc_url(home_url('/cif/processos/' . rawurlencode((string)$occurrence['processo_uuid']))) ?>">Abrir processo vinculado</a><?php else: ?><p>Quando a ocorrência exigir nova CIF, abra o processo administrativo correspondente. O fato, a comunicação e os documentos anexados à ocorrência serão reaproveitados sem duplicar o arquivo físico.</p><?php $processType=(string)$occurrence['tipo_codigo']==='DESGASTE'?'DANO':(string)$occurrence['tipo_codigo']; ?><a class="cif-button cif-button--secondary" href="<?= esc_url(add_query_arg(['agente'=>(string)$occurrence['agente_uuid'],'tipo'=>$processType,'fato'=>(string)$occurrence['data_fato'],'comunicado'=>(string)$occurrence['data_comunicacao'],'ocorrencia'=>(string)$occurrence['uuid']],home_url('/cif/processos/novo'))) ?>">Abrir processo de emissão</a><?php endif; ?></section>
<?php endif; ?>
<?php if($canRecover && (string)$occurrence['status']==='ABERTA' && in_array((string)$occurrence['tipo_codigo'],['PERDA','FURTO','ROUBO'],true)): ?><section class="cif-section cif-panel"><h2>Documento recuperado</h2><p>Se ainda não houver nova CIF ativa, a emissão suspensa será reativada. Se já tiver sido substituída, será recolhida para inutilização e permanecerá encerrada.</p><form method="post" action="<?= esc_url(home_url('/cif/ocorrencias/'.rawurlencode((string)$occurrence['uuid']).'/recuperar')) ?>"><?php smtt_cif_nonce_field('smtt_cif_occurrence_recover_'.(string)$occurrence['uuid'],'smtt_cif_nonce'); ?><button class="cif-button cif-button--primary" type="submit">Registrar recuperação da CIF</button></form></section><?php endif; ?>
<section class="cif-section"><a class="cif-button cif-button--ghost" href="<?= esc_url($returnToReport ?? (home_url('/cif/emissoes/'.rawurlencode((string)$occurrence['emissao_uuid'])) . '#historico-cif')) ?>"><?= $returnToReport !== null ? 'Voltar ao relatório' : 'Voltar à emissão' ?></a></section>
<?php require SMTT_CIF_GESTAO_PATH . 'templates/layout/footer.php'; ?>
